[{"category":"section","location":"mms/#MMS-example-and-validation-with-PySPEDAS","page":"MMS example","text":"Current density from the four MMS spacecraft: burst-mode FGM fields, whose timestamps differ between spacecraft, and MEC positions at a lower cadence.\n\nusing MultiSpacecraftAnalysis\nusing TimeseriesUtilities: mapsamples\nusing CDAWeb: CDAWeb, getdata\nusing DimensionalData, Dates\nusing CairoMakie, SpacePhysicsMakie\n\nt0 = DateTime(\"2016-12-09T09:02\")\nt1 = DateTime(\"2016-12-09T09:04\")\nload(dataset, var) = DimArray(getdata(CDAWeb.Dataset(dataset)[var], t0, t1))\n\n# FGM data comes with the magnitude as a fourth component\nfields = ntuple(i -> load(\"MMS$(i)_FGM_BRST_L2\", \"mms$(i)_fgm_b_gse_brst_l2\")[X(1:3)], 4)\npositions = ntuple(i -> load(\"MMS$(i)_MEC_BRST_L2_EPHT89D\", \"mms$(i)_mec_r_gse\"), 4)\n\nout = tlingradest(fields, positions)\n\u001b[90m┌ \u001b[39m\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m×\u001b[38;5;81m3\u001b[39m DimStack\u001b[90m ┐\u001b[39m\n\u001b[90m├────────────────────┴─────────────────────────────────────────────────── dims ┐\u001b[39m\n  \u001b[38;5;209m↓ \u001b[39m\u001b[38;5;209mX\u001b[39m Categorical{String} \u001b[38;5;209m[\"Bx GSE\", …, \"Bz GSE\"]\u001b[39m \u001b[38;5;244mUnordered\u001b[39m,\n  \u001b[38;5;32m→ \u001b[39m\u001b[38;5;32mTi\u001b[39m Sampled{CommonDataFormat.TT2000} \u001b[38;5;32m[2016-12-09T09:02:00.010743014, …, 2016-12-09T09:03:59.989034162]\u001b[39m \u001b[38;5;244mForwardOrdered\u001b[39m \u001b[38;5;244mIrregular\u001b[39m \u001b[38;5;244mPoints\u001b[39m,\n  \u001b[38;5;81m↗ \u001b[39m\u001b[38;5;81m∂\u001b[39m Categorical{String} \u001b[38;5;81m[\"Bx GSE\", …, \"Bz GSE\"]\u001b[39m \u001b[38;5;244mForwardOrdered\u001b[39m\n\u001b[90m├────────────────────────────────────────────────────────────────────── layers ┤\u001b[39m\n\u001b[38;5;37m  :rbar\u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;209mX\u001b[39m, \u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :vbar\u001b[39m\u001b[90m eltype: \u001b[39mFloat32\u001b[90m dims: \u001b[39m\u001b[38;5;209mX\u001b[39m, \u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :vmag\u001b[39m\u001b[90m eltype: \u001b[39mFloat32\u001b[90m dims: \u001b[39m\u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :grad\u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;81m∂\u001b[39m, \u001b[38;5;209mX\u001b[39m, \u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;81m3\u001b[39m×\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :div \u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :curl\u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;209mX\u001b[39m, \u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :curv\u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;209mX\u001b[39m, \u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;209m3\u001b[39m×\u001b[38;5;32m15358\u001b[39m\n\u001b[38;5;37m  :rc  \u001b[39m\u001b[90m eltype: \u001b[39mFloat64\u001b[90m dims: \u001b[39m\u001b[38;5;32mTi\u001b[39m\u001b[90m size: \u001b[39m\u001b[38;5;32m15358\u001b[39m\n\u001b[90m└──────────────────────────────────────────────────────────────────────────────┘\u001b[39m\n\nusing LinearAlgebra\nusing Unitful\n\nunitify(x, unit) = x isa Quantity ? x : x * unit\n\n# Current density along 𝐁, from 𝐁 and ∇ × 𝐁 = μ₀𝐉\nfunction jparallel(𝐁, curl𝐁)\n    𝐁 = unitify.(𝐁, u\"nT\")\n    curl𝐁 = unitify.(curl𝐁, u\"nT/km\")\n    return dot(curl𝐁, 𝐁) / norm(𝐁) / Unitful.μ0 |> u\"nA/m^2\"\nend\n\njp = mapsamples(jparallel, out.vbar, out.curl)\njp = DimensionalData.rebuild(jp; name = :jpar, metadata = Dict(:ylabel => \"J∥\\n(nA/m²)\"))\ntplot((out.vbar, out.div, out.curl, out.curv, jp))\nFigureAxes()","title":"MMS example and validation with PySPEDAS"},{"category":"section","location":"mms/#Validation-with-PySPEDAS","page":"MMS example","text":"using PySPEDAS\nusing PythonCall\nusing Test\n@py import pyspedas.projects.mms: mec, fgm, curlometer, lingradest as py_lingradest\ntrange = string.([t0, t1])\nfgm_vars = @py fgm(probe=[1, 2, 3, 4], trange=trange, data_rate=\"brst\", time_clip=true, varformat=\"*_gse_*\")\nmec_vars = @py mec(probe=[1, 2, 3, 4], trange=trange, data_rate=\"brst\", time_clip=true, varformat=\"*_r_gse\")\nposits_py = [\"mms$(i)_mec_r_gse\" for i in 1:4]\nfields_py = [\"mms$(i)_fgm_b_gse_brst_l2\" for i in 1:4]\ncurlometer(fields=fields_py, positions=posits_py)\njp_py = PySPEDAS.get_data(\"jpar\")\n\n# pyspedas interpolates over the full range and leaves NaN at both ends; `tlingradest` clips to the common range\n@test ustrip.(u\"nA/m^2\", parent(jp)) ≈ 1e9 .* vec(jp_py)[2:end-1] rtol=1e-4\n\u001b[32m\u001b[1mTest Passed\u001b[22m\u001b[39m","title":"Validation with PySPEDAS"},{"category":"section","location":"mms/#Benchmark","page":"MMS example","text":"using Chairmarks\n@b tlingradest($fields, $positions), py_lingradest(fields=$fields_py, positions=$posits_py), curlometer(fields=$fields_py, positions=$posits_py)\n(4.115 ms (237 allocs: 7.153 MiB), 2.528 s (99 allocs: 2.156 KiB), 5.053 s (99 allocs: 1.594 KiB))","title":"Benchmark"},{"category":"section","location":"mms/#References","page":"MMS example","text":"MMS curlometer example notebook","title":"References"},{"category":"section","location":"#MultiSpacecraftAnalysis","page":"Home","text":"Multi-spacecraft analysis methods in Julia.\n\n(Image: DOI) (Image: version)","title":"MultiSpacecraftAnalysis"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"MultiSpacecraftAnalysis\")","title":"Installation"},{"category":"section","location":"#Reciprocal-vectors","page":"Home","text":"Paschmann and Daly [1], Chapter 4, Paschmann and Daly [2], Chapter 14, ","title":"Reciprocal vectors"},{"category":"section","location":"#Estimation-of-spatial-gradients","page":"Home","text":"Since tildeg and tildeboldsymbolV are linear functions, the calculation of spatial derivatives, such as the gradient of some scalar function or the divergence or curl of a vector function, can be done quite easily. The results are:\n\nbeginaligned\nnabla g simeq nabla tildeg  =sum_alpha=0^3 boldsymbolk_alpha g_alpha \nhatboldsymbole cdot nabla g simeq hatboldsymbole cdot nabla tildeg  =sum_alpha=0^3left(hatboldsymbole cdot boldsymbolk_alpharight) g_alpha \nnabla cdot boldsymbolV simeq nabla cdot tildeboldsymbolV  =sum_alpha=0^3 boldsymbolk_alpha cdot boldsymbolV_alpha \nnabla times boldsymbolV simeq nabla times tildeboldsymbolV  =sum_alpha=0^3 boldsymbolk_alpha times boldsymbolV_alpha\nendaligned","title":"Estimation of spatial gradients"},{"category":"section","location":"#Multi-spacecraft-timing","page":"Home","text":"","title":"Multi-spacecraft timing"},{"category":"section","location":"#API","page":"Home","text":"\n\nG. Paschmann and P. W. Daly. Multi-Spacecraft Analysis Methods Revisited (ESA Communications, 2008).\n\n\n\nG. Paschmann and P. W. Daly. Analysis Methods for Multi-Spacecraft Data (ESA Publications Division, 2000).\n\n\n\n","title":"API"},{"category":"function","location":"#MultiSpacecraftAnalysis.reciprocal_vectors","page":"Home","text":"reciprocal_vectors(rs)\n\nReciprocal vectors {𝒌_α} of N ≥ 4 positions rs. For N = 4 this is the reciprocal base of the tetrahedron,\n\n𝒌_α = frac𝐫_βγ  𝐫_βλ𝐫_βα  (𝐫_βγ  𝐫_βλ) quad 𝐫_αβ = 𝐫_β - 𝐫_α\n\nfor (α, β, γ, λ) a cyclic permutation of (1, 2, 3, 4). Otherwise the generalized reciprocal vectors 𝐪_α = 𝐑^-1 (𝐫_α - 𝐫_b), which coincide with 𝒌_α at N = 4.\n\nSee also: position_tensor\n\nReferences\n\nVogt, Paschmann & Chanteur (2008), Reciprocal vectors, in Multi-spacecraft analysis methods revisited, ISSI SR-008, Ch. 4.\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.reciprocal_vectors"},{"category":"function","location":"#MultiSpacecraftAnalysis.position_tensor","page":"Home","text":"𝐑 = _α (𝐫_α-𝐫_b) (𝐫_α-𝐫_b) = _α 𝐫_α 𝐫_α-𝐫_b 𝐫_b\n\nwith 𝐫_b = _α 𝐫_α  N and N is the number of positions.\n\nReferences\n\nPaschmann and Daly [1] Paschmann & Daly, 2008. Section 4.7\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.position_tensor"},{"category":"function","location":"#MultiSpacecraftAnalysis.volumetric_tensor","page":"Home","text":"volumetric_tensor(rs::AbstractVector{<:AbstractVector})\n\nfrac1N 𝐑.\n\nSee also: position_tensor\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.volumetric_tensor"},{"category":"function","location":"#MultiSpacecraftAnalysis.tetrahedron_quality","page":"Home","text":"Calculate tetrahedron quality factors\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.tetrahedron_quality"},{"category":"function","location":"#MultiSpacecraftAnalysis.lingradest","page":"Home","text":"lingradest(Vs, Rs)\n\nCompute spatial derivatives such as grad, div, curl and curvature using the reciprocal vector technique (linear interpolation), from vectors Vs of any vector field 𝐕 measured at positions Rs by N ≥ 4 spacecraft.\n\nReturns\n\nA named tuple containing:   • rbar: Barycenter position (mean of Rs)   • vbar: Field at the barycenter (mean of Vs)   • vmag: Field magnitude at the barycenter   • grad: Linear gradient estimator, grad[i, j] = ∂_i V_j   • div: Linear divergence estimator   • curl: Linear curl estimator   • curv: Field-line curvature vector 𝐯 · ∇𝐯, with 𝐯 = 𝐕 / |𝐕|   • rc: Field-line curvature radius\n\nReferences\n\nBased on the method of Chanteur (ISSI, 1998, Ch. 11).\n\nlingradest.pro\nlingradest.py\n\n\n\n\n\nlingradest(Vs, Rs; dim = nothing, select = nothing)\n\nVs and Rs are tuples or vectors of matrices, each with time along dim, which defaults to each input's own time dimension (e.g. Ti of a DimArray) and is required for plain matrices. Returns a StructVector with one row per time sample.\n\nPass select = (:field1, :field2, ...) to materialize only the listed columns.\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.lingradest"},{"category":"function","location":"#MultiSpacecraftAnalysis.tlingradest","page":"Home","text":"tlingradest(Vs, Rs; dim = nothing, select = nothing, kws...)\n\nlingradest on time series, after tsync(Vs..., Rs...; dim, kws...) onto the times of first(Vs).\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.tlingradest"},{"category":"function","location":"#MultiSpacecraftAnalysis.ConstantVelocityApproach","page":"Home","text":"ConstantVelocityApproach(positions, times)\nCVA(positions, times)\n\nConstant Velocity Approach (CVA): boundary normal n and speed V from the crossing times at N ≥ 4 spacecraft positions (a collection of 3-vectors), solving the timing equation (𝐫_α - 𝐫_1)  𝐧  V = t_α - t_1 (least squares for N > 4).\n\n\n\n\n\nConstantVelocityApproach(positions, times, durations)\n\nGiven durations of the boundary crossings, calculate the thickness of the boundary\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.ConstantVelocityApproach"},{"category":"method","location":"#MultiSpacecraftAnalysis.ConstantVelocityApproach-Tuple{Any, Any, Any}","page":"Home","text":"ConstantVelocityApproach(positions, times, durations)\n\nGiven durations of the boundary crossings, calculate the thickness of the boundary\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.ConstantVelocityApproach"},{"category":"method","location":"#MultiSpacecraftAnalysis.ConstantVelocityApproach-Tuple{Any, Any}","page":"Home","text":"ConstantVelocityApproach(positions, times)\nCVA(positions, times)\n\nConstant Velocity Approach (CVA): boundary normal n and speed V from the crossing times at N ≥ 4 spacecraft positions (a collection of 3-vectors), solving the timing equation (𝐫_α - 𝐫_1)  𝐧  V = t_α - t_1 (least squares for N > 4).\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.ConstantVelocityApproach"},{"category":"method","location":"#MultiSpacecraftAnalysis.lingradest-Tuple{Any, Any}","page":"Home","text":"lingradest(Vs, Rs)\n\nCompute spatial derivatives such as grad, div, curl and curvature using the reciprocal vector technique (linear interpolation), from vectors Vs of any vector field 𝐕 measured at positions Rs by N ≥ 4 spacecraft.\n\nReturns\n\nA named tuple containing:   • rbar: Barycenter position (mean of Rs)   • vbar: Field at the barycenter (mean of Vs)   • vmag: Field magnitude at the barycenter   • grad: Linear gradient estimator, grad[i, j] = ∂_i V_j   • div: Linear divergence estimator   • curl: Linear curl estimator   • curv: Field-line curvature vector 𝐯 · ∇𝐯, with 𝐯 = 𝐕 / |𝐕|   • rc: Field-line curvature radius\n\nReferences\n\nBased on the method of Chanteur (ISSI, 1998, Ch. 11).\n\nlingradest.pro\nlingradest.py\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.lingradest"},{"category":"method","location":"#MultiSpacecraftAnalysis.lingradest-Tuple{Union{Tuple{Vararg{AbstractMatrix}}, AbstractVector{<:AbstractMatrix}}, Union{Tuple{Vararg{AbstractMatrix}}, AbstractVector{<:AbstractMatrix}}}","page":"Home","text":"lingradest(Vs, Rs; dim = nothing, select = nothing)\n\nVs and Rs are tuples or vectors of matrices, each with time along dim, which defaults to each input's own time dimension (e.g. Ti of a DimArray) and is required for plain matrices. Returns a StructVector with one row per time sample.\n\nPass select = (:field1, :field2, ...) to materialize only the listed columns.\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.lingradest"},{"category":"method","location":"#MultiSpacecraftAnalysis.m2nV-Tuple{Any}","page":"Home","text":"Convert slowness vector 𝐦 = 𝐧V to normal vector and velocity\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.m2nV"},{"category":"function","location":"#MultiSpacecraftAnalysis.position_tensor-2","page":"Home","text":"𝐑 = _α (𝐫_α-𝐫_b) (𝐫_α-𝐫_b) = _α 𝐫_α 𝐫_α-𝐫_b 𝐫_b\n\nwith 𝐫_b = _α 𝐫_α  N and N is the number of positions.\n\nReferences\n\nPaschmann and Daly [1] Paschmann & Daly, 2008. Section 4.7\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.position_tensor"},{"category":"method","location":"#MultiSpacecraftAnalysis.reciprocal_vectors-Tuple{Any}","page":"Home","text":"reciprocal_vectors(rs)\n\nReciprocal vectors {𝒌_α} of N ≥ 4 positions rs. For N = 4 this is the reciprocal base of the tetrahedron,\n\n𝒌_α = frac𝐫_βγ  𝐫_βλ𝐫_βα  (𝐫_βγ  𝐫_βλ) quad 𝐫_αβ = 𝐫_β - 𝐫_α\n\nfor (α, β, γ, λ) a cyclic permutation of (1, 2, 3, 4). Otherwise the generalized reciprocal vectors 𝐪_α = 𝐑^-1 (𝐫_α - 𝐫_b), which coincide with 𝒌_α at N = 4.\n\nSee also: position_tensor\n\nReferences\n\nVogt, Paschmann & Chanteur (2008), Reciprocal vectors, in Multi-spacecraft analysis methods revisited, ISSI SR-008, Ch. 4.\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.reciprocal_vectors"},{"category":"method","location":"#MultiSpacecraftAnalysis.tetrahedron_quality-Tuple{AbstractVector{<:AbstractVector}}","page":"Home","text":"Calculate tetrahedron quality factors\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.tetrahedron_quality"},{"category":"method","location":"#MultiSpacecraftAnalysis.tlingradest-Tuple{Any, Any}","page":"Home","text":"tlingradest(Vs, Rs; dim = nothing, select = nothing, kws...)\n\nlingradest on time series, after tsync(Vs..., Rs...; dim, kws...) onto the times of first(Vs).\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.tlingradest"},{"category":"method","location":"#MultiSpacecraftAnalysis.volumetric_tensor-Tuple{AbstractVector{<:AbstractVector}}","page":"Home","text":"volumetric_tensor(rs::AbstractVector{<:AbstractVector})\n\nfrac1N 𝐑.\n\nSee also: position_tensor\n\n\n\n\n\n","title":"MultiSpacecraftAnalysis.volumetric_tensor"}]
